 * @param needs_shooting  Output: needs shooting?
 * @param errmsg          Input/Output: Error message
 * @return the error status
 */

int input_needs_shooting_for_target(struct file_content * pfc,
                                    enum target_names target_name,
                                    double target_value,
                                    int * needs_shooting,
                                    ErrorMsg errmsg){

  *needs_shooting = _TRUE_;
  switch (target_name){
  case Omega_dcdmdr:
  case omega_dcdmdr:
  case Omega_scf:
  case Omega_ini_dcdm:
  case omega_ini_dcdm:
    /* Check that Omega's or omega's are nonzero: */
    if (target_value == 0.)
      *needs_shooting = _FALSE_;
    break;
  case f_gedf:
    class_test((target_value < 0.) || (target_value >= 1.),
               errmsg,
               "The requested value of 'f_gedf' must be in the interval [0,1), not %g.",
               target_value);
    if (target_value == 0.)
      *needs_shooting = _FALSE_;
    break;
  case f_gedf_2:
    class_test((target_value < 0.) || (target_value >= 1.),
               errmsg,
               "The requested value of 'f_gedf_2' must be in the interval [0,1), not %g.",
               target_value);
    if (target_value == 0.)
      *needs_shooting = _FALSE_;
    break;
  default:
    /* Default is no additional checks */
    *needs_shooting = _TRUE_;
    break;
  }

  return _SUCCESS_;

}

