    class_stop(error_message,"root must be bracketed in zriddr.");
  }
  class_stop(error_message,"Failure in int.");
}


/**
 * Related to 'shooting': we define here a reasonable analytic guess
 * for each unknown parameter as a function of its target
 * parameter. We must also estimate dxdy, i.e. how the unknown
 * parameter responds to the target parameter.  This can simply be
 * estimated as the derivative of the guess formula.
 *
 * @param xguess Output: guess for unkown parameter x given target parameter y
 * @param dxdy   Output: guess for derivative dx/dy
 * @param pfzw   Input : pointer to workspace containing targets, unkown parameters and other relevant information
 * @param errmsg Input/Output: Error message
 * @return the error status
 */

int input_get_guess(double *xguess,
                    double *dxdy,
                    struct fzerofun_workspace * pfzw,
                    ErrorMsg errmsg){

  /** Summary: */

  /** Define local variables */
  struct precision pr;        /* for precision parameters */
  struct background ba;       /* for cosmological background */
  struct thermodynamics th;           /* for thermodynamics */
  struct perturbations pt;         /* for source functions */
  struct transfer tr;        /* for transfer functions */
  struct primordial pm;       /* for primordial spectra */
  struct harmonic hr;          /* for output spectra */
  struct fourier fo;        /* for non-linear spectra */
  struct lensing le;          /* for lensed spectra */
  struct distortions sd;      /* for spectral distortions */
  struct output op;           /* for output files */
  int i;
  double Omega_M, a_decay, gamma, Omega0_dcdmdr=1.0;
  double rho_no_gedf, Omega_r, Omega_m;
  int index_guess;
  int index_ncdm; double N_nonur_guess = 0.0;
  int index_f_gedf = -1, index_f_gedf_2 = -1;
  double rho_no_gedf_1 = 0., rho_no_gedf_2 = 0.;
  double k_gedf = 0., k_gedf_2 = 0.;
  double integral_gedf_ac1 = 0., integral_gedf_ac2 = 0.;
  double integral_gedf2_ac1 = 0., integral_gedf2_ac2 = 0.;
  double w_tmp, dw_tmp, det;

  /* Cheat to read only known parameters: */
  pfzw->fc.size -= pfzw->target_size;

  /* Assume for now shooting did not fail */
  ba.shooting_failed = _FALSE_;

  class_call(input_read_precisions(&(pfzw->fc),&pr,&ba,&th,&pt,&tr,&pm,&hr,&fo,&le,&sd,&op,
                                   errmsg),
             errmsg,
             errmsg);
  class_call(input_read_parameters(&(pfzw->fc),&pr,&ba,&th,&pt,&tr,&pm,&hr,&fo,&le,&sd,&op,
                                   errmsg),
             errmsg,
             errmsg);

  pfzw->fc.size += pfzw->target_size;

  /** Estimate dxdy */
  for (index_guess=0; index_guess < pfzw->target_size; index_guess++) {
    switch (pfzw->target_name[index_guess]) {
    case theta_s:
    case theta_s_100:
      xguess[index_guess] = 3.54*pow(pfzw->target_value[index_guess],2)-5.455*pfzw->target_value[index_guess]+2.548;
      dxdy[index_guess] = (7.08*pfzw->target_value[index_guess]-5.455);
      /** Update pb to reflect guess */
      ba.h = xguess[index_guess];
      ba.H0 = ba.h *  1.e5 / _c_;
      // printf(" Shooting guess of h = %-15g, \n", xguess[index_guess]);
      break;
    case Neff:
      for(index_ncdm=0;index_ncdm<ba.N_ncdm;++index_ncdm){
        N_nonur_guess += ba.deg_ncdm[index_ncdm]* 1.0132;
      }
      N_nonur_guess += ba.Omega0_idr/ba.Omega0_g/(7./8.)*pow(11./4.,(4./3.));
      xguess[index_guess] = pfzw->target_value[index_guess] - N_nonur_guess;
      dxdy[index_guess] = 1.;
      break;
    case Omega_dcdmdr:
      Omega_M = ba.Omega0_cdm+ba.Omega0_idm+ba.Omega0_dcdmdr+ba.Omega0_b;
      /* *
       * This formula is exact in a Matter + Lambda Universe, but only for Omega_dcdm,
       * not the combined.
       * sqrt_one_minus_M = sqrt(1.0 - Omega_M);
       * xguess[index_guess] = pfzw->target_value[index_guess]*
       *                       exp(2./3.*ba.Gamma_dcdm/ba.H0*
       *                       atanh(sqrt_one_minus_M)/sqrt_one_minus_M);
       * dxdy[index_guess] = 1.0;//exp(2./3.*ba.Gamma_dcdm/ba.H0*atanh(sqrt_one_minus_M)/sqrt_one_minus_M);
       * */
      gamma = ba.Gamma_dcdm/ba.H0;
      if (gamma < 1)
        a_decay = 1.0;
      else
        a_decay = pow(1+(gamma*gamma-1.)/Omega_M,-1./3.);
      xguess[index_guess] = pfzw->target_value[index_guess]/a_decay;
      dxdy[index_guess] = 1./a_decay;
      break;
    case omega_dcdmdr:
      Omega_M = ba.Omega0_cdm+ba.Omega0_idm+ba.Omega0_dcdmdr+ba.Omega0_b;
      gamma = ba.Gamma_dcdm/ba.H0;
      if (gamma < 1)
        a_decay = 1.0;
      else
        a_decay = pow(1+(gamma*gamma-1.)/Omega_M,-1./3.);
      xguess[index_guess] = pfzw->target_value[index_guess]/ba.h/ba.h/a_decay;
      dxdy[index_guess] = 1./a_decay/ba.h/ba.h;
      break;
    case Omega_scf:
      /* *
       * This guess is arbitrary, something nice using WKB should be implemented.
       * Version 2 uses a fit
       * xguess[index_guess] = 1.77835*pow(ba.Omega0_scf,-2./7.);
       * dxdy[index_guess] = -0.5081*pow(ba.Omega0_scf,-9./7.)`;
       * Version 3: use attractor solution
       * */
      if (ba.scf_tuning_index == 0){
        xguess[index_guess] = sqrt(3.0/ba.Omega0_scf);
        dxdy[index_guess] = -0.5*sqrt(3.0)*pow(ba.Omega0_scf,-1.5);
      }
      else{
        /* Default: take the passed value as xguess and set dxdy to 1. */
        xguess[index_guess] = ba.scf_parameters[ba.scf_tuning_index];
        dxdy[index_guess] = 1.;
      }
      break;
    case omega_ini_dcdm:
      Omega0_dcdmdr = 1./(ba.h*ba.h);
    case Omega_ini_dcdm:
      /* This works since correspondence is Omega_ini_dcdm -> Omega_dcdmdr and
         omega_ini_dcdm -> omega_dcdmdr */
      Omega0_dcdmdr *=pfzw->target_value[index_guess];
      Omega_M = ba.Omega0_cdm+ba.Omega0_idm+Omega0_dcdmdr+ba.Omega0_b;
      gamma = ba.Gamma_dcdm/ba.H0;
      if (gamma < 1)
        a_decay = 1.0;
      else
        a_decay = pow(1+(gamma*gamma-1.)/Omega_M,-1./3.);
      xguess[index_guess] = pfzw->target_value[index_guess]*a_decay;
      dxdy[index_guess] = a_decay;
      if (gamma > 100)
        dxdy[index_guess] *= gamma/100;
      break;
    case f_gedf:
      class_test((pfzw->target_value[index_guess] < 0.) || (pfzw->target_value[index_guess] >= 1.),
                 errmsg,
                 "The requested value of 'f_gedf' must be in the interval [0,1), not %g.",
                 pfzw->target_value[index_guess]);
      Omega_r = ba.Omega0_g + ba.Omega0_ur + ba.Omega0_idr;
      Omega_m = ba.Omega0_b + ba.Omega0_cdm + ba.Omega0_idm + ba.Omega0_dcdmdr;
      rho_no_gedf = pow(ba.H0,2) * (Omega_r/pow(ba.ac_gedf,4)
                                    + Omega_m/pow(ba.ac_gedf,3)
                                    + ba.Omega0_lambda
                                    + ba.Omega0_fld);
      rho_no_gedf_1 = rho_no_gedf;
      k_gedf = pfzw->target_value[index_guess] / (1. - pfzw->target_value[index_guess]);
      xguess[index_guess] = pfzw->target_value[index_guess] * rho_no_gedf
        / (1. - pfzw->target_value[index_guess]);
      dxdy[index_guess] = rho_no_gedf
        / pow(1. - pfzw->target_value[index_guess],2);
      index_f_gedf = index_guess;
      break;
    case f_gedf_2:
      class_test((pfzw->target_value[index_guess] < 0.) || (pfzw->target_value[index_guess] >= 1.),
                 errmsg,
                 "The requested value of 'f_gedf_2' must be in the interval [0,1), not %g.",
                 pfzw->target_value[index_guess]);
      Omega_r = ba.Omega0_g + ba.Omega0_ur + ba.Omega0_idr;
      Omega_m = ba.Omega0_b + ba.Omega0_cdm + ba.Omega0_idm + ba.Omega0_dcdmdr;
      rho_no_gedf = pow(ba.H0,2) * (Omega_r/pow(ba.ac_gedf_2,4)
                                    + Omega_m/pow(ba.ac_gedf_2,3)
                                    + ba.Omega0_lambda
                                    + ba.Omega0_fld);
      rho_no_gedf_2 = rho_no_gedf;
      k_gedf_2 = pfzw->target_value[index_guess] / (1. - pfzw->target_value[index_guess]);
      xguess[index_guess] = pfzw->target_value[index_guess] * rho_no_gedf
        / (1. - pfzw->target_value[index_guess]);
      dxdy[index_guess] = rho_no_gedf
        / pow(1. - pfzw->target_value[index_guess],2);
      index_f_gedf_2 = index_guess;
      break;

    case sigma8:
      /* Assume linear relationship between A_s and sigma8 and fix coefficient
         according to vanilla LambdaCDM. Should be good enough... */
      xguess[index_guess] = 2.43e-9/0.87659*pfzw->target_value[index_guess];
      dxdy[index_guess] = 2.43e-9/0.87659;
      break;
    case S8:
      /* Assume linear relationship between A_s and S8 and fix coefficient
         according to vanilla LambdaCDM. Should be good enough... */
      xguess[index_guess] = 2.43e-9/0.891*pfzw->target_value[index_guess];
      dxdy[index_guess] = 2.43e-9/0.891;
      break;
    }
  }

  if ((index_f_gedf >= 0) && (index_f_gedf_2 >= 0)) {
    class_call(background_w_gedf(&ba,ba.ac_gedf,&w_tmp,&dw_tmp,&integral_gedf_ac1),
               ba.error_message,
               errmsg);
    class_call(background_w_gedf(&ba,ba.ac_gedf_2,&w_tmp,&dw_tmp,&integral_gedf_ac2),
               ba.error_message,
               errmsg);
    class_call(background_w_gedf_2(&ba,ba.ac_gedf,&w_tmp,&dw_tmp,&integral_gedf2_ac1),
               ba.error_message,
               errmsg);
    class_call(background_w_gedf_2(&ba,ba.ac_gedf_2,&w_tmp,&dw_tmp,&integral_gedf2_ac2),
               ba.error_message,
               errmsg);

    det = 1. - k_gedf * k_gedf_2 * exp((integral_gedf_ac2 - integral_gedf_ac1)
                                       + (integral_gedf2_ac1 - integral_gedf2_ac2));

    if (fabs(det) > 1e-12) {
      xguess[index_f_gedf] =
        k_gedf * (rho_no_gedf_1 + k_gedf_2 * rho_no_gedf_2 * exp(integral_gedf2_ac1 - integral_gedf2_ac2)) / det;
      xguess[index_f_gedf_2] =
        k_gedf_2 * (rho_no_gedf_2 + k_gedf * rho_no_gedf_1 * exp(integral_gedf_ac2 - integral_gedf_ac1)) / det;
    }
    else {
      /* Fall back to the uncoupled estimates above when the coupled system
         becomes nearly singular. The root finder can refine from there. */
      dxdy[index_f_gedf] = rho_no_gedf_1
        / pow(1. - pfzw->target_value[index_f_gedf],2);
      dxdy[index_f_gedf_2] = rho_no_gedf_2
        / pow(1. - pfzw->target_value[index_f_gedf_2],2);
    }
  }

  for (i=0; i<pfzw->fc.size; i++) {
    pfzw->fc.read[i] = _FALSE_;
  }

  /** - Deallocate everything allocated by input_read_parameters */
  background_free_input(&ba);
  thermodynamics_free_input(&th);
  perturbations_free_input(&pt);

  return _SUCCESS_;

}

